function yazi_tarih(string $t): string {
    $ay = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];
    [$y, $m, $d] = array_map('intval', explode('-', $t) + [0, 0, 0]);
    return $d . ' ' . ($ay[$m] ?? '') . ' ' . $y;
}
